WITH combined AS ( SELECT 'REFUNDED' AS role, cr.cr_refunded_hdemo_sk AS hd_demo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr UNION ALL SELECT 'RETURNING' AS role, cr.cr_returning_hdemo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr ) SELECT role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_buy_potential, SUM(combined.cr_return_quantity) AS total_return_qty, SUM(combined.cr_net_loss) AS total_net_loss, COUNT(*) AS return_records, ROW_NUMBER() OVER (PARTITION BY role ORDER BY SUM(combined.cr_net_loss) ASC) AS loss_rank FROM combined JOIN household_demographics hd ON combined.hd_demo_sk = hd.hd_demo_sk GROUP BY role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_buy_potential HAVING SUM(combined.cr_return_quantity) > 100 ORDER BY role, loss_rank
